class_name DungeonGenerator
extends Node

@export var seed: int = 12345
@export var width: int = 64
@export var height: int = 64
@export var wall_threshold: float = 0.0

var _rooms: Array[Rect2i] = []

func generate(target: TileMapLayer) -> void:
	# 1. Clear target
	target.clear()
	_rooms.clear()

	# 2. Setup FastNoiseLite
	var noise = FastNoiseLite.new()
	noise.seed = seed
	noise.noise_type = FastNoiseLite.TYPE_SIMPLEX
	noise.frequency = 0.1

	# 3. Base noise pass
	for x in range(width):
		for y in range(height):
			var val = noise.get_noise_2d(x, y)
			if val > wall_threshold:
				target.set_cell(Vector2i(x, y), 1, Vector2i(0, 0)) # Wall
			else:
				target.set_cell(Vector2i(x, y), 0, Vector2i(0, 0)) # Floor

	# 4. Generate rooms deterministically using a seeded RNG
	var rng = RandomNumberGenerator.new()
	rng.seed = seed

	var attempts = 0
	while _rooms.size() < 3 and attempts < 2000:
		attempts += 1
		# Room sizes between 5 and 12
		var rw = rng.randi_range(5, 12)
		var rh = rng.randi_range(5, 12)
		# Ensure rooms are fully inside the interior region (1..width-2, 1..height-2)
		# rx must be in [1, width - 1 - rw]
		# ry must be in [1, height - 1 - rh]
		if width - 1 - rw < 1 or height - 1 - rh < 1:
			continue
		var rx = rng.randi_range(1, width - 1 - rw)
		var ry = rng.randi_range(1, height - 1 - rh)

		var room = Rect2i(rx, ry, rw, rh)

		# Check overlap with existing rooms
		var overlaps = false
		for r in _rooms:
			if r.intersects(room):
				overlaps = true
				break

		if not overlaps:
			_rooms.append(room)

	# 5. Carve rooms
	for r in _rooms:
		for x in range(r.position.x, r.position.x + r.size.x):
			for y in range(r.position.y, r.position.y + r.size.y):
				target.set_cell(Vector2i(x, y), 0, Vector2i(0, 0))

	# 6. Carve corridors
	if _rooms.size() >= 3:
		# Connect Room 0 to Room 1
		_carve_l_corridor(target, _rooms[0], _rooms[1])
		# Connect Room 1 to Room 2
		_carve_l_corridor(target, _rooms[1], _rooms[2])

	# 7. Enforce outer boundary walls
	for x in range(width):
		target.set_cell(Vector2i(x, 0), 1, Vector2i(0, 0))
		target.set_cell(Vector2i(x, height - 1), 1, Vector2i(0, 0))
	for y in range(height):
		target.set_cell(Vector2i(0, y), 1, Vector2i(0, 0))
		target.set_cell(Vector2i(width - 1, y), 1, Vector2i(0, 0))

func _carve_l_corridor(target: TileMapLayer, r1: Rect2i, r2: Rect2i) -> void:
	var center_1 = r1.position + r1.size / 2
	var center_2 = r2.position + r2.size / 2

	# Horizontal then Vertical
	var start_x = min(center_1.x, center_2.x)
	var end_x = max(center_1.x, center_2.x)
	for x in range(start_x, end_x + 1):
		target.set_cell(Vector2i(x, center_1.y), 0, Vector2i(0, 0))

	var start_y = min(center_1.y, center_2.y)
	var end_y = max(center_1.y, center_2.y)
	for y in range(start_y, end_y + 1):
		target.set_cell(Vector2i(center_2.x, y), 0, Vector2i(0, 0))

func count_floor_tiles(target: TileMapLayer) -> int:
	var count = 0
	for x in range(width):
		for y in range(height):
			if target.get_cell_source_id(Vector2i(x, y)) == 0:
				count += 1
	return count

func find_rooms() -> Array[Rect2i]:
	return _rooms

extends SceneTree

func _init():
	print("Running dungeon generator tests...")

	# Load tileset
	var tileset = load("res://tilesets/dungeon.tres")
	if tileset == null:
		print("Error: Could not load tileset")
		quit(1)
		return

	# Instantiate TileMapLayer
	var target = TileMapLayer.new()
	target.tile_set = tileset

	# Instantiate DungeonGenerator
	var generator = load("res://scripts/DungeonGenerator.gd").new()
	generator.seed = 12345
	generator.width = 64
	generator.height = 64
	generator.wall_threshold = 0.0

	# Generate 1
	generator.generate(target)
	var floor_count_1 = generator.count_floor_tiles(target)
	var rooms_1 = generator.find_rooms()

	print("Run 1 (seed=12345):")
	print("  Floor count: ", floor_count_1)
	print("  Rooms: ", rooms_1)

	# Save run 1 cells
	var cells_1 = {}
	for x in range(generator.width):
		for y in range(generator.height):
			cells_1[Vector2i(x, y)] = target.get_cell_source_id(Vector2i(x, y))

	# Generate 2 (same seed)
	generator.generate(target)
	var floor_count_2 = generator.count_floor_tiles(target)
	var rooms_2 = generator.find_rooms()

	print("Run 2 (seed=12345):")
	print("  Floor count: ", floor_count_2)
	print("  Rooms: ", rooms_2)

	# Compare run 1 and run 2
	var match_same_seed = true
	for x in range(generator.width):
		for y in range(generator.height):
			if cells_1[Vector2i(x, y)] != target.get_cell_source_id(Vector2i(x, y)):
				match_same_seed = false
				break

	if not match_same_seed:
		print("Error: Run 1 and Run 2 with the same seed do not match!")
		quit(1)
		return
	else:
		print("Success: Run 1 and Run 2 with the same seed are identical!")

	# Check room non-overlapping and containment
	for i in range(rooms_1.size()):
		var r1 = rooms_1[i]
		# Check containment
		if r1.position.x < 1 or r1.position.y < 1 or r1.position.x + r1.size.x > generator.width - 1 or r1.position.y + r1.size.y > generator.height - 1:
			print("Error: Room ", r1, " is not fully contained in the interior!")
			quit(1)
			return
		for j in range(i + 1, rooms_1.size()):
			var r2 = rooms_1[j]
			if r1.intersects(r2):
				print("Error: Room ", r1, " and ", r2, " overlap!")
				quit(1)
				return
	print("Success: Rooms are pairwise non-overlapping and fully contained in interior!")

	# Generate 3 (different seed)
	generator.seed = 99999
	generator.generate(target)
	var floor_count_3 = generator.count_floor_tiles(target)
	var rooms_3 = generator.find_rooms()

	print("Run 3 (seed=99999):")
	print("  Floor count: ", floor_count_3)
	print("  Rooms: ", rooms_3)

	# Compare run 1 and run 3 (should be different)
	var match_diff_seed = true
	for x in range(generator.width):
		for y in range(generator.height):
			if cells_1[Vector2i(x, y)] != target.get_cell_source_id(Vector2i(x, y)):
				match_diff_seed = false
				break

	if match_diff_seed:
		print("Error: Run 1 and Run 3 with different seeds are identical!")
		quit(1)
		return
	else:
		print("Success: Run 1 and Run 3 with different seeds are different!")

	print("All tests passed successfully!")
	quit()

extends Node

@onready var tile_map_layer: TileMapLayer = $TileMapLayer
@onready var dungeon_generator: DungeonGenerator = $DungeonGenerator

func _ready():
	print("Main scene ready. Generating dungeon...")
	dungeon_generator.generate(tile_map_layer)
	print("Dungeon generated successfully. Floor tiles: ", dungeon_generator.count_floor_tiles(tile_map_layer))

